use std::fs

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut cap = 1
    let mut first = true
    let mut ks: Vec<int> = []
    let mut vs: Vec<int> = []
    for line in text.lines() {
        let parts: Vec<string> = line.split_whitespace().collect()
        if parts.len() == 0 { continue }
        if first {
            cap = parts[0].parse::<int>().unwrap_or(1)
            first = false
            continue
        }
        let cmd = parts[0]
        if cmd == "put" {
            let k = parts[1].parse::<int>().unwrap_or(0)
            let v = parts[2].parse::<int>().unwrap_or(0)
            let mut nk: Vec<int> = [k]
            let mut nv: Vec<int> = [v]
            let mut i = 0
            while i < ks.len() {
                if ks[i] != k {
                    nk.push(ks[i])
                    nv.push(vs[i])
                }
                i += 1
            }
            if nk.len() as int > cap {
                println("evict ${nk[nk.len() - 1]}")
                nk.pop()
                nv.pop()
            }
            ks = nk
            vs = nv
        } else if cmd == "get" {
            let k = parts[1].parse::<int>().unwrap_or(0)
            let mut found = -1
            let mut idx = 0
            let mut i = 0
            while i < ks.len() {
                if ks[i] == k {
                    found = vs[i]
                    idx = i
                    i = ks.len()
                } else {
                    i += 1
                }
            }
            let present = ks.len() > 0 && ks[idx] == k
            if !present {
                println("-1")
            } else {
                let mut nk: Vec<int> = [k]
                let mut nv: Vec<int> = [found]
                let mut j = 0
                while j < ks.len() {
                    if ks[j] != k {
                        nk.push(ks[j])
                        nv.push(vs[j])
                    }
                    j += 1
                }
                ks = nk
                vs = nv
                println("${found}")
            }
        } else if cmd == "keys" {
            if ks.len() == 0 {
                println("<empty>")
            } else {
                let mut s = ""
                let mut i = 0
                while i < ks.len() {
                    if i > 0 { s = s + " " }
                    s = s + "${ks[i]}"
                    i += 1
                }
                println("${s}")
            }
        }
    }
}

